//! 🧪️ Native pin ordering preserves the actual original String allocations through partial heapsort.
use super::*;
fn pin(rank:usize,wide:usize)->CompositionPin{CompositionPin{child_ref:semio_framework_artifact_reference::ArtifactRef{artifact_id:format!("energy-{}{rank:04}","λ".repeat(wide)),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.energy.model".into(),standard:"1".into(),subset:"*".into()}},checkpoint_id:format!("ck-{rank}")}}
#[test]
fn original_pin_order_sorts_in_place_and_closes_every_cancelled_comparison(){let law:serde_json::Value=serde_json::from_str(include_str!("pin-order.json")).unwrap();let mut cases:Vec<(Vec<usize>,bool,usize,Option<Vec<usize>>)>=law["cases"].as_array().unwrap().iter().map(|case|(case["order"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as usize).collect(),case["duplicate"]==true,0,case["expected"].as_array().map(|rows|rows.iter().map(|n|n.as_u64().unwrap()as usize).collect()))).collect();cases.push(((0..law["manyCount"].as_u64().unwrap()as usize).rev().collect(),false,0,Some((0..law["manyCount"].as_u64().unwrap()as usize).collect())));cases.push((vec![2,0,1],false,law["wideRepeat"].as_u64().unwrap()as usize,Some(vec![0,1,2])));let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};for(order,duplicate,wide,expected)in cases{for cut in [Some(0),Some(1),Some(7),Some(32),Some(128),None]{let mut pins:Vec<_>=order.iter().map(|rank|pin(*rank,wide)).collect();let mut pointers:Vec<_>=pins.iter().map(|p|p.child_ref.artifact_id.as_ptr()as usize).collect();pointers.sort();let original=pins.as_ptr();let mut owner=OriginalCompositionPinOrder::default();let mut refused=false;for index in 0..1048576{if owner.ready()||cut==Some(index){break}let d=owner.demands();for axis in 0..3{let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,_=>denied.maximum_depth=0};let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut pins,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut pins,grant));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));match result{Ok(p)=>assert!(p.fits(grant)),Err(error)=>{assert!(duplicate);assert!(error.retained_progress().fits(grant));refused=true;break}}assert!(index<1048575);}if cut.is_none(){assert_eq!(refused,duplicate);if !duplicate{assert!(owner.ready());let actual:Vec<_>=pins.iter().map(|p|p.checkpoint_id.as_str()).collect();let expected:Vec<_>=expected.as_ref().unwrap().iter().map(|rank|format!("ck-{rank}")).collect();assert_eq!(actual,expected);}}let mut retained:Vec<_>=pins.iter().map(|p|p.child_ref.artifact_id.as_ptr()as usize).collect();retained.sort();assert_eq!(retained,pointers);assert_eq!(pins.as_ptr(),original);let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant));assert!(p.fits(grant));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert!(owner.terminal_is_empty());}}}
